// Rebuild the reviewed Tidewatch scene and two loop presets. No simulation runs in the game.
// --check compares every generated byte; --force explicitly replaces generated artwork.
import { access, mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { compileWaves, renderProject, inspectProject, resolveReferences, prepareScene, renderScene, encodeGIF, encodePNG, formatJSON } from '../../src/index.js';
import { cosDeg, sinDeg } from '../../src/craft.js';

const root = fileURLToPath(new URL('../../', import.meta.url));
const folder = path.join(root, 'showcase', 'waves');
const json = async file => JSON.parse(await readFile(file, 'utf8'));

// Illustrative comparison: independent positive rings, with their strongest value coloured.
// The 1.45 gain keeps them readable at the same thresholds. This is not the particle compiler,
// and not a physical reference solution. It deliberately has no cancellation between sources.
function independentRings(source, compiled) {
  const recipe = structuredClone(compiled);
  let frame = 0;
  for (const effect of Object.values(source.effects)) for (let f = 0; f < effect.frames; f++) {
    const rows = Array.from({ length: source.height }, (_, y) => Array.from({ length: source.width }, (_, x) => {
      let value = Math.max(...effect.sources.map(s => {
        const dx = x - s.at[0], dy = y - s.at[1], stretch = s.stretch ?? [1, 1];
        const position = s.kind === 'radial' ? Math.sqrt((dx / stretch[0]) ** 2 + (dy / stretch[1]) ** 2) : dx * cosDeg(s.angle ?? 0) + dy * sinDeg(s.angle ?? 0);
        return (s.amplitude ?? 1) * cosDeg(360 * (position / s.wavelength - (s.cycles ?? 1) * f / effect.frames) + (s.phase ?? 0));
      })) * 1.45;
      const m = effect.mask, distance = Math.sqrt(((x - m.at[0]) / m.radius[0]) ** 2 + ((y - m.at[1]) / m.radius[1]) ** 2);
      const fade = Math.max(0, Math.min(1, (1 - distance) / m.feather));
      value *= fade * fade * (3 - 2 * fade);
      let key = '.';
      effect.look.thresholds.forEach((threshold, i) => { if (value >= threshold) key = effect.look.colors[i]; });
      return key;
    }).join(''));
    recipe.frames[frame++].layers.find(layer => layer.name === 'wave').ops[0].rows = rows;
  }
  return recipe;
}

export async function buildWaveShowcase() {
  const files = new Map(), recipes = {}, baseline = {}, report = [];
  for (const name of ['interference', 'portal']) {
    const source = await json(path.join(root, 'examples', `${name}.wave.json`)), started = performance.now();
    const { recipe, warnings } = compileWaves(source), compileMs = performance.now() - started;
    const project = renderProject(recipe), view = inspectProject(project, { native: true });
    recipes[name] = recipe; baseline[name] = independentRings(source, recipe);
    files.set(`${name}.json`, Buffer.from(formatJSON(recipe)));
    files.set(`${name}.gif`, Buffer.from(encodeGIF(project.frames, project.width, project.height, { loop: true, scale: 4 }).data));
    files.set(`${name}-contact.png`, Buffer.from(encodePNG(view.nativeSheet.data, view.nativeSheet.width, view.nativeSheet.height)));
    report.push({ name, frames: project.frames.length, width: project.width, height: project.height, compileMs: Math.round(compileMs), warnings });
  }
  const original = path.join(root, 'showcase/tidewatch/art/scenes/tidewatch-headland-night.scene.json');
  const raw = await json(original);
  raw.name = 'wave-headland'; raw.lighting.ambient = 0.46;
  raw.instances = raw.instances.filter(i => !((i.asset === 'props' || i.asset === 'rocks') && i.at[0] > 150 && i.at[0] < 215 && i.at[1] > 70 && i.at[1] < 130));
  raw.instances.find(i => i.name === 'keeper').at = [152, 134];
  raw.instances.push({ asset: 'interference', at: [69, 113], anchor: 'frame', animation: 'resonate', lit: false },
    { asset: 'portal', at: [186, 121], anchor: 'frame', animation: 'open', lit: false });
  // Keep the scene editable and portable within the checkout instead of copying Tidewatch artwork.
  const rebase = file => path.relative(folder, path.resolve(path.dirname(original), file)).split(path.sep).join('/');
  for (const [name, asset] of Object.entries(raw.assets)) raw.assets[name] = typeof asset === 'string' ? rebase(asset) : Object.fromEntries(Object.entries(asset).map(([k, v]) => [k, rebase(v)]));
  const { document: base } = await resolveReferences(raw, { baseDir: folder });
  raw.assets.interference = 'interference.json'; raw.assets.portal = 'portal.json';
  files.set('scene.scene.json', Buffer.from(formatJSON(raw)));
  for (const [name, assets] of [['scene', recipes], ['independent-rings', baseline]]) {
    const scene = prepareScene({ ...base, assets: { ...base.assets, ...assets } });
    const frames = Array.from({ length: 40 }, (_, i) => ({ ...renderScene(scene, { time: i * 60 }), duration: 60 }));
    files.set(`${name}.gif`, Buffer.from(encodeGIF(frames, 240, 160, { loop: true, scale: 3 }).data));
    files.set(`${name}.png`, Buffer.from(encodePNG(frames[8].data, 240, 160)));
  }
  return { files, report };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.slice(2).some(arg => !['--check', '--force'].includes(arg))) throw new Error('Use --check or --force.');
  const check = process.argv.includes('--check'), force = process.argv.includes('--force');
  const { files, report } = await buildWaveShowcase();
  if (check) {
    for (const [file, bytes] of files) if (!bytes.equals(await readFile(path.join(folder, file)))) throw new Error(`Generated artwork differs: ${file}. Review it before rebuilding with --force.`);
  } else {
    if (!force) for (const file of files.keys()) {
      if (await access(path.join(folder, file)).then(() => true, () => false)) throw new Error(`Refusing to replace ${file}; use --force for an intentional rebuild.`);
    }
    await mkdir(folder, { recursive: true });
    for (const [file, bytes] of files) await writeFile(path.join(folder, file), bytes, { flag: force ? 'w' : 'wx' });
  }
  console.log(`${check ? 'Verified' : 'Wrote'} ${files.size} wave showcase files.`); console.table(report);
}
